            <li>Saved Apr 18</li>
          </ul>

          <div class="actions">
            <button type="button" class="button-secondary">Download image</button>
            <button type="button" class="trigger" aria-haspopup="dialog">
              Delete image
            </button>
          </div>

          <p id="delete-status" class="status" aria-live="polite" tabindex="-1"></p>
        </div>
      </article>
    </main>

    <footer class="site-footer">
      <p>Manage saved previews and library items.</p>
    </footer>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <div class="dialog-content">
        <div class="dialog-icon" aria-hidden="true">!</div>
        <h2 id="dialog-title" class="dialog-title">Delete this image?</h2>
        <p id="dialog-description" class="dialog-copy">
          This will remove "Alpine Retreat" from your library. This action cannot be undone.
        </p>
        <div class="dialog-actions">
          <button type="button" class="button-secondary" data-close-dialog>
            Keep image
          </button>
          <button type="button" class="button-danger" data-confirm-delete>
            Delete image
          </button>
        </div>
      </div>
    </dialog>

    <script>
      const deleteDialog = document.querySelector("#delete-dialog");
      const openDialogButton = document.querySelector(".trigger");
      const closeDialogButton = document.querySelector("[data-close-dialog]");
      const confirmDeleteButton = document.querySelector("[data-confirm-delete]");
      const statusMessage = document.querySelector("#delete-status");

      let previouslyFocusedElement = null;
      let imageWasDeleted = false;

      function openDeleteDialog() {
        previouslyFocusedElement = document.activeElement;
        deleteDialog.showModal();
        closeDialogButton.focus();
      }

      function closeDeleteDialog() {
        deleteDialog.close();
      }

      openDialogButton.addEventListener("click", openDeleteDialog);
      closeDialogButton.addEventListener("click", closeDeleteDialog);

      confirmDeleteButton.addEventListener("click", () => {
        imageWasDeleted = true;
        statusMessage.textContent = "Image deleted from your library.";
        openDialogButton.disabled = true;
        openDialogButton.textContent = "Image deleted";
        deleteDialog.close("deleted");
      });

      deleteDialog.addEventListener("click", (event) => {
        if (event.target === deleteDialog) {
          closeDeleteDialog();
        }
      });

      deleteDialog.addEventListener("close", () => {
        if (imageWasDeleted) {
          statusMessage.focus();
        } else if (previouslyFocusedElement && typeof previouslyFocusedElement.focus === "function") {
          previouslyFocusedElement.focus();
        }
      });
    </script>
